mapper.select:
        select
        userCollect.*,
        users.nick_name,
        users.head_img,
        foods.food_name,
        foods.banner_img
        from user_collect userCollect
        left join users users on userCollect.user_id = users.id
		left join foods foods on userCollect.food_id = foods.id

            and userCollect.id = #{id}
            and userCollect.food_id = #{foodId}
            and userCollect.user_id = #{userId}
            and userCollect.type_id = #{typeId}
            and userCollect.create_time = #{createTime}
            and users.nick_name like concat('%',#{nickName},'%')
            and users.head_img = #{headImg}
            and foods.food_name like concat('%',#{foodName},'%')
            and foods.banner_img = #{bannerImg}


            limit #{current},#{pageSize}

        select count(*) from user_collect userCollect
        left join users users on userCollect.user_id = users.id
		left join foods foods on userCollect.food_id = foods.id

            and userCollect.id = #{id}
            and userCollect.food_id = #{foodId}
            and userCollect.user_id = #{userId}
            and userCollect.type_id = #{typeId}
            and userCollect.create_time = #{createTime}
            and users.nick_name like concat('%',#{nickName},'%')
            and users.head_img = #{headImg}
            and foods.food_name like concat('%',#{foodName},'%')
            and foods.banner_img = #{bannerImg}
